create role anon;create role authenticated;create role service_role bypassrls;create schema auth;create schema storage;create schema bia_identity_private;create schema devoluciones_privado;
create table auth.users(id uuid primary key,email text,raw_app_meta_data jsonb default '{}',raw_user_meta_data jsonb default '{}',created_at timestamptz default now());
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create function public.usuario_password_actualizada() returns boolean language sql stable security definer as $$select exists(select 1 from auth.users where id=auth.uid() and coalesce(raw_app_meta_data->>'must_change_password','false')<>'true')$$;
create table storage.objects(id uuid default gen_random_uuid(),bucket_id text,name text);alter table storage.objects enable row level security;
create function storage.foldername(name text) returns text[] language sql immutable as $$select (string_to_array(name,'/'))[1:array_length(string_to_array(name,'/'),1)-1]$$;
create table public.actividad_participaciones("id" uuid default gen_random_uuid(),"cronometro_id" uuid,"colaborador_id" uuid,"colaborador_nombre" text,"fecha" date,"actividad" text,"segundos_inicio" integer,"segundos_fin" integer,"segundos" integer,"estado" text,"motivo_retiro" text,"retirado_por" uuid,"retirado_por_email" text,"retirado_en" timestamp with time zone,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"sede" text);
alter table public.actividad_participaciones enable row level security;
create table public.actividades_catalogo("id" uuid default gen_random_uuid(),"nombre" text,"min_participantes" integer,"max_participantes" integer,"activo" boolean default true,"orden" integer default 100,"creado_por" uuid,"actualizado_por" uuid,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"sede" text);
alter table public.actividades_catalogo enable row level security;
create table public.auditoria_cierres_dia("id" uuid default gen_random_uuid(),"fecha" date,"accion" text,"observacion" text,"usuario_id" uuid,"usuario_email" text,"created_at" timestamp with time zone,"sede" text);
alter table public.auditoria_cierres_dia enable row level security;
create table public.auditoria_eliminaciones("id" uuid default gen_random_uuid(),"tipo_registro" text,"registro_id" uuid,"datos_eliminados" jsonb,"motivo" text,"eliminado_por" uuid,"eliminado_por_email" text,"eliminado_en" timestamp with time zone,"sede" text);
alter table public.auditoria_eliminaciones enable row level security;
create table public.auditoria_modificaciones("id" uuid default gen_random_uuid(),"tipo_registro" text,"registro_id" uuid,"datos_anteriores" jsonb,"datos_nuevos" jsonb,"motivo" text,"modificado_por" uuid,"modificado_por_email" text,"modificado_en" timestamp with time zone,"timer_id" uuid,"sede" text);
alter table public.auditoria_modificaciones enable row level security;
create table public.ausencias_personal("id" uuid default gen_random_uuid(),"colaborador_id" uuid,"colaborador_nombre" text,"fecha" date,"horas_ausencia" numeric(5,2),"motivo" text,"registrado_por" uuid,"registrado_por_email" text,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"tipo_ausencia" text,"sede" text);
alter table public.ausencias_personal enable row level security;
create table public.cierres_diarios("fecha" date,"observacion" text,"cerrado_por" uuid,"cerrado_por_email" text,"cerrado_en" timestamp with time zone,"estado" text,"reabierto_por" uuid,"reabierto_por_email" text,"reabierto_en" timestamp with time zone,"actualizado_en" timestamp with time zone,"sede" text);
alter table public.cierres_diarios enable row level security;
create table public.colaboradores("id" uuid default gen_random_uuid(),"nombre" text,"codigo" text,"activo" boolean default true,"orden" integer default 100,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"sede" text,"numero_reporte" integer);
alter table public.colaboradores enable row level security;
create table public.cronometros("id" uuid default gen_random_uuid(),"categoria" text,"empleado" text,"estado" text,"inicio" timestamp with time zone,"segundos_acumulados" integer,"datos" jsonb,"version" integer,"iniciado_por" uuid,"actualizado_por" uuid,"actualizado_en" timestamp with time zone,"finalizado_en" timestamp with time zone,"colaborador_id" uuid,"sede" text);
alter table public.cronometros enable row level security;
create table public.devoluciones("id" uuid default gen_random_uuid(),"solicitud_id" uuid,"gestion" text,"fecha_registro" timestamp with time zone,"sede" text,"gestor_n1" integer,"gestor_n2" integer,"gestor_n4" integer,"liquidadora" text,"factura" text,"cliente" text,"observacion" text,"bodega_origen" text,"bodega_destino" text,"comentario" text,"estado" text,"fecha_entrega_liquidadora" timestamp with time zone,"fecha_nota_debito" timestamp with time zone,"fecha_ingreso_gp" timestamp with time zone,"fecha_finalizado" timestamp with time zone,"creado_por" uuid,"version" integer,"eliminado_at" timestamp with time zone,"eliminado_por" uuid);
alter table public.devoluciones enable row level security;
create table public.devoluciones_entregas("id" uuid default gen_random_uuid(),"sede" text,"gestor_n2" integer,"liquidadora" text,"celular" text,"creado_por" uuid,"creado_at" timestamp with time zone,"cerrado_at" timestamp with time zone,"fecha_impresion" timestamp with time zone,"version" integer);
alter table public.devoluciones_entregas enable row level security;
create table public.errores_preparacion("id" uuid default gen_random_uuid(),"sede" text,"historial_preparacion_id" uuid,"timer_id" uuid,"fecha_preparacion" date,"tipo_error" text,"cantidad" integer,"observacion" text,"registrado_por" uuid,"registrado_por_email" text,"created_at" timestamp with time zone,"updated_at" timestamp with time zone);
alter table public.errores_preparacion enable row level security;
create table public.errores_preparacion_participantes("error_id" uuid,"sede" text,"colaborador_id" uuid,"numero_reporte" integer,"created_at" timestamp with time zone);
alter table public.errores_preparacion_participantes enable row level security;
create table public.historial_actividades("id" uuid default gen_random_uuid(),"timer_id" uuid,"created_at" timestamp with time zone,"fecha" date,"empleado" text,"actividad" text,"segundos" integer,"finalizado_por" uuid,"finalizado_por_email" text,"colaborador_id" uuid,"participantes" jsonb,"sede" text);
alter table public.historial_actividades enable row level security;
create table public.historial_preparaciones("id" uuid default gen_random_uuid(),"timer_id" uuid,"created_at" timestamp with time zone,"fecha_preparacion" date,"empleado" text,"zona" text,"tipo" text,"facturas" integer,"libras" numeric(12,2),"segundos" integer,"finalizado_por" uuid,"finalizado_por_email" text,"colaborador_id" uuid,"sede" text);
alter table public.historial_preparaciones enable row level security;
create table public.metas_productividad("id" uuid default gen_random_uuid(),"facturas_hora" numeric(12,2),"libras_hora" numeric(12,2),"productividad_minima" numeric(6,2),"actividad_alerta_min" integer,"activo" boolean default true,"actualizado_por" uuid,"actualizado_por_email" text,"updated_at" timestamp with time zone,"sede" text);
alter table public.metas_productividad enable row level security;
create table public.pausas_cronometros("id" uuid default gen_random_uuid(),"cronometro_id" uuid,"motivo" text,"pausado_en" timestamp with time zone,"reanudado_en" timestamp with time zone,"pausado_por" uuid,"pausado_por_email" text,"sede" text);
alter table public.pausas_cronometros enable row level security;
create table public.preparacion_participaciones("id" uuid default gen_random_uuid(),"cronometro_id" uuid,"colaborador_id" uuid,"colaborador_nombre" text,"fecha" date,"zona" text,"tipo" text,"facturas" integer,"libras" numeric(12,2),"segundos_inicio" integer,"segundos_fin" integer,"segundos" integer,"estado" text,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"sede" text);
alter table public.preparacion_participaciones enable row level security;
create table public.sedes("codigo" text,"nombre" text);
alter table public.sedes enable row level security;
create table public.supplier_claims("id" uuid default gen_random_uuid(),"document_number" text,"supplier" text,"transport" text,"driver_name" text,"plate_number" text,"claim_number" text,"claim_date" date,"agency" text,"has_damage_claim" boolean,"observations" text,"received_by" text,"driver_signature_name" text,"items" jsonb,"container_photos" text[],"damage_photos" text[],"status" text,"created_by" uuid,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"management_number" text,"transfer_origin" text);
alter table public.supplier_claims enable row level security;
create table public.usuarios("id" integer generated by default as identity,"usuario" character varying(50),"correo" character varying(100),"rol" character varying(20),"contraseña" text,"nombre_corto" text,"password_hash" text,"must_change_password" boolean,"temporal_password" boolean,"failed_login_attempts" integer,"locked_until" timestamp with time zone,"dni" text,"sede" text,"tipo_bodega" text,"updated_at" timestamp with time zone,"auth_user_id" uuid,"activo" boolean default true,"puede_inventariar_otras_sedes" boolean);
alter table public.usuarios enable row level security;
create table public.usuarios_sedes("id" uuid default gen_random_uuid(),"user_id" uuid,"email" text,"nombre" text,"sede" text,"rol" text,"puede_cierre_dia" boolean,"activo" boolean default true,"created_at" timestamp with time zone,"updated_at" timestamp with time zone);
alter table public.usuarios_sedes enable row level security;
alter table usuarios_sedes add unique(user_id,sede);alter table usuarios add unique(auth_user_id);
create function bia_identity_private.sync_identity(p_id uuid) returns void language sql as $$insert into public.usuarios(auth_user_id,correo,nombre_corto,activo) select a.id,a.email,s.nombre,s.activo from auth.users a join public.usuarios_sedes s on s.user_id=a.id where a.id=p_id limit 1 on conflict(auth_user_id) do nothing$$;
grant usage on schema public,auth to authenticated,anon,service_role;

create table public.codigos(codigo text);alter table public.codigos enable row level security;
